        if code is None and self.dry and os.environ.get("DRY_CODE"):   # 仿真干跑没有真盒(同"识别借落点"): 借一个码走完后半程(直飞/放置/飞回), 2026-11-02
            code = os.environ["DRY_CODE"]; say("(仿真干跑: 没读到码, 借用 DRY_CODE=%s 走后半程)" % code)
        from flows.decisions import Decision
        from actions.scan import unwind_j6
        def drop_route(why):
            if spins:
                unwind_j6(self.arm, spins)      # 丢回路线不经mid且用movel(只认最短路不知缠绕) → 先解绕
            self.card(drop(self.arm, self.suck, dry=self.dry)); return "%s, 已丢回, 臂在 home" % why
        if not self.judge(Decision("有码?", code is not None, ("有: " + code) if code else "无 → 丢回", "" if code else "四面轮询无读数(无码面或未吸到)")).go:
            return drop_route("四面未读到码")

        box_mm = None                               # 这盒的[宽,高,厚](上位机回去处带的); None=格口基准盒
        front_mm = None                             # 这一列账上的队首(上位机回去处带的, 2026-11-17 可选); 设备按它修正推进量
        if self.destination_hook is not None:      # 问去处模式: 设备只报码, 上位机定格口/坑位/尺寸; 设备不查追溯API
            say("◇ 判断: 去处 → 问上位机(码 %s)" % code)
            ans = self.destination_hook(code, (L, W, H))
            if self.abort_req:
                raise Stop("上位机立即停止(持货在扫码位) → 人工: act.sh drop 后 act.sh goto home")
            if ans is None:
                self.judge(Decision("去处", False, "上位机超时未答 → 丢回", "")); return drop_route("上位机未给去处")
            if ans.get("action") == "discard":
                self.judge(Decision("去处", False, "上位机指示丢回", ans.get("reason", ""))); return drop_route("上位机指示丢回: " + ans.get("reason", ""))
            slot, pit = ans["slot"], tuple(ans["pit"]); box_mm = ans.get("box_mm"); front_mm = ans.get("front_mm")
            self.judge(Decision("去处", True, "%s 坑位%s" % (slot, list(pit)), "尺寸%s" % box_mm))
            from flows.decisions import recognize_face_dims
            dec = recognize_face_dims(L, W, ans["box_mm"], ans.get("name", "")) if ans.get("box_mm") else recognize_face(code, L, W)
        else:
            dec = recognize_face(code, L, W)
        if not self.judge(dec).go:
            return drop_route("认脸不通过")

        from tools.grasp.slotname import canon as _canon
        direct = "scan_hover_to_%s" % _canon(slot)
        if os.path.exists(os.path.join(ROOT, "config", "paths", direct + ".json")):   # 2026-11-02 扫码位直飞格口(不经 mid; 路径库有才走, 没有照旧经 mid)
            if spins >= 2:                  # 同下: 转≥2次先原地解绕, 免得接头段 J6 转太多
                unwind_j6(self.arm, spins)
            self.card(fly(self.arm, direct, payload=self.payload, dry=self.dry, approach=True))   # 接头: 扫码位→scan_hover 关节直线并队(抬起+J6回零, 不停车)
        elif self.merge:    # 扫码位→mid→格口 一条track(接头并队, mid不停车, J6顺路回零)
            self.card(fly(self.arm, "mid_to_%s" % slot, payload=self.payload, dry=self.dry, approach=True))
        else:               # 保守走法(新格口验收)
            if spins >= 2:                  # 转≥2次: movej带J6回零反而慢(1.0rad/s vs 原地movel≈1.9rad/s, 实测去mid 1.9→4.9s) → 原地解绕
                unwind_j6(self.arm, spins)
            self.card(goto(self.arm, "mid", payload=self.payload))   # 转1次: movej关节直线顺路把J6带回零(省≈0.7s)
            self.card(fly(self.arm, "mid_to_%s" % slot, payload=self.payload, dry=self.dry))
        d, pit_ok = choose_pit(slot, *(pit or (None, None, None)), box_mm=box_mm)
        self.judge(d)
        if not d.go:
            raise Stop("坑位越界, 持货停在 %s 悬停点 → 人工: act.sh fly %s_to_mid 后处置" % (slot, slot))
        self.card(place(self.arm, self.suck, self.rot, slot, pit_ok, dry=self.dry, box_mm=box_mm, front_mm=front_mm))
        self.payload = P.NONE
        # 回程并队试过(2026-09-03): 省1s但尾段按飞行1.4/0.7冲到home急刹, 用户听到刹车声; 尾段稀疏化无效(末段峰速仍1.35rad/s).
        # 退回: 飞到mid停, 单独movej回home(1.3/0.3, 柔). 去程也不并(急弯净零).
        self.card(fly(self.arm, "%s_to_mid" % slot, payload=P.NONE, dry=self.dry, approach=True))   # approach: 开了基准照的格口臂停在拍照点, 接一小段到路径起点不停顿
        self.card(goto(self.arm, "home"))
        return "已上架 %s %s, 臂在 home" % (slot, d.verdict.split(" ")[-1])


def open_resources(arm, dry, feed_mode="auto"):
    """连臂/看门狗/使能/吸盘/腕转/视觉/扫码/上苗机(仅auto). 失败抛AssertionError. 返回dict"""
    res = {"suck": None, "rot": None, "vision": None, "scanner": None, "feeder": None}
    assert arm.connect(), "机械臂连不上"
    from actions.guard import install as _guard
    _guard(arm)
    arm.enable()
    from actions.robot_state import ensure_auto
    res["opmode_note"] = ensure_auto(arm._cobot)
    if dry:
        assert arm._cobot.get_simulation_state() is True, "--dry 要求控制器仿真模式"
        from tools.grasp.place_slot import _NoIO
        res["suck"] = res["rot"] = _NoIO()
    else:
        from hardware.gripper import DucoSuction
        from actions.rotator import make_rotator
        suck = DucoSuction(); assert suck.connect(), "吸盘连不上"; res["suck"] = suck
        rot = make_rotator(knob("place", "rotator_settle_s")); assert rot.connect(home=False), "腕转电机连不上"; res["rot"] = rot
    from services.vision_client import VisionClient
    from services.scan_client import ScanClient
    res["vision"] = VisionClient.try_connect(); res["scanner"] = ScanClient.try_connect()
