# ── 一个任务 = 一次开硬件 + N 盒循环 ──
def _run(self, t):
    import flows.store_one_box as F
    t.state = "running"; t.started = time.time(); t.stage_code = "STARTING"
    t.emit("task_start", feed=t.req.feed, destination=t.req.destination, slot=t.req.slot, pits=t.req.pits, stop=t.req.stop.model_dump(),
           dest=t.req.dest if t.req.type in ("retrieve", "outbound") else None, reason=t.req.reason, items=len(t.req.items or []) if t.req.type in ("retrieve", "outbound") else None)
    _stage_of = {"去 home": "HOMING", "识别": "LOCATING", "送料": "FEEDING", "吸取": "PICKING", "扫码": "SCANNING", "去 mid": "TO_TRANSIT",
                 "飞路径": "TRANSFERRING", "放置": "PUTAWAY", "丢回": "REJECTING", "复位": "RECOVERING", "取货": "RETRIEVING", "投放": "DISPENSING"}

    def on_text(s):
        s = s.strip()
        if s.startswith("[已放好]"):                       # 放置⑥吹开成功 → 即刻记账
            t.progress["stored"] += 1; t.current["stored_emitted"] = True
            t.emit("stored", box_seq=t.box_seq, code=t.current.get("code"), slot=t.current.get("slot"), pit=t.current.get("pit"), **_xi(t.current.get("pit")))
        elif s.startswith("◇ 判断: 货物丢失"):
            t.current["lost_text"] = s.replace("◇ 判断: 货物丢失 → ", ""); t.emit("text", box_seq=t.box_seq, text=s)
