class _BlowWatch:
    """2026-11-26 查吹气异响: 开吹后后台每 ~20ms 读一次真空开关 DI4, 记下真空多久才破(DI4 变 0)。
    只记录、不改动作(臂照旧吹 blow_s 后退出)。吸盘有自己的 IO 连接, 臂运动走另一条连接; stop() 必须在 blow_stop 前调用。"""

    def __init__(self, suck):
        import threading
        self.suck, self.t0, self.t_break, self.t_retreat, self.n = suck, time.time(), None, None, 0
        self._stop = threading.Event()
        self._th = threading.Thread(target=self._run, daemon=True) if getattr(suck, "vacuum", None) else None
        if self._th: self._th.start()

    def _run(self):
        while not self._stop.is_set() and time.time() - self.t0 < 5.0:
            v = self.suck.vacuum(); self.n += 1
            if v is False:
                self.t_break = time.time() - self.t0; return
            time.sleep(0.02)

    def retreat(self):
        self.t_retreat = time.time() - self.t0

    def stop(self, slot, x_mm, idx):
        self._stop.set()
        if self._th: self._th.join(1.0)
        tr = self.t_retreat if self.t_retreat is not None else float("nan")
        if self.t_break is None:
            verdict = "整段吹气都没破(读了%d次)" % self.n
        elif self.t_break <= tr:
            verdict = "退出前已破"
        else:
            verdict = "退出开始后 %.2fs 才破" % (self.t_break - tr)
        tb = ("%.2fs" % self.t_break) if self.t_break is not None else "-"
